    using System;
using System.Collections.Generic;

class Node {
    public int data;
    public Node next;

    public Node(int x) {
        data = x;
        next = null;
    }
}

// Custom comparator class for min heap
class NodeComparer : IComparer<Node> {
    public int Compare(Node a, Node b) {
        if (a.data > b.data)
            return 1;
        else if (a.data < b.data)
            return -1;
        return 0;
    }
}

class GfG {

    // Function to merge K sorted linked lists
    static Node mergeKLists(List<Node> arr) {
        PriorityQueue<Node> pq = new PriorityQueue<Node>(new NodeComparer());

        // Insert the head nodes of k lists 
        foreach (Node head in arr) {
            if (head != null) pq.Enqueue(head);
        }

        Node dummy = new Node(-1);
        Node tail = dummy;

        while (pq.Count > 0) {

            // Pop the min node 
            Node top = pq.Dequeue();

            // Append the node into list 
            tail.next = top;
            tail = top;

            // If top node has next node,
            // add it to the heap.
            if (top.next != null) {
                pq.Enqueue(top.next);
            }
        }

        return dummy.next;
    }

    static void printList(Node node) {
        while (node != null) {
            Console.Write(node.data);
            if(node.next != null){
                Console.Write("->");
            }
            node = node.next;
        }
    }

    static void Main(string[] args) {

        List<Node> arr = new List<Node>();

        arr.Add(new Node(1));
        arr[0].next = new Node(3);
        arr[0].next.next = new Node(5);
